  if (![left, right, top, bottom, width, height, clientLeft, clientTop, clientWidth, clientHeight, offsetWidth, offsetHeight].every(Number.isFinite)
    || width < 0 || height < 0 || clientWidth < 0 || clientHeight < 0 || offsetWidth < 0 || offsetHeight < 0) return null;
